"use client"

import {
  Fragment,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react"
import { Button } from "@/components/fiori/ui/button"
import { Checkbox } from "@/components/fiori/ui/checkbox"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/fiori/ui/table"
import { cn } from "@/lib/fiori/utils"
import { findPageScrollContainer } from "./dynamic-page"
import { SapIcon } from "./sap-icon"
import { useResponsiveTableNavigation } from "./use-responsive-table-navigation"
import "./list-report.css"

export type ResponsiveTableColumn<T> = {
  id: string
  label: ReactNode
  render: (row: T) => ReactNode
  /** Container width below which this column moves to label/value pop-in. */
  minWidth?: number
  align?: "start" | "end"
  className?: string
}
export type ResponsiveTableCounts = {
  total: number
  loaded: number
  selected: number
}
export type ResponsiveTableProps<T> = {
  rows: T[]
  columns: ResponsiveTableColumn<T>[]
  getRowId: (row: T) => string
  getRowLabel?: (row: T) => string
  selectedIds?: string[]
  onSelectionChange?: (ids: string[]) => void
  onRowNavigate?: (id: string) => void
  sort?: { key: string; direction: "asc" | "desc" }
  growingPageSize?: number
  scrollContainerRef?: RefObject<HTMLElement | null>
  labels: {
    table: string
    selectAll?: string
    selectRow?: (row: T) => string
    navigateRow?: (row: T) => string
    noData?: string
    columnHeaders?: string
    navigation?: string
    status?: (counts: ResponsiveTableCounts) => string
  }
}

/** Read-only responsive rows, growing and navigation; query/sort/business state stay outside. */
export function ResponsiveTable<T>({
  rows,
  columns,
  getRowId,
  getRowLabel,
  selectedIds = [],
  onSelectionChange,
  onRowNavigate,
  sort,
  growingPageSize = 20,
  scrollContainerRef,
  labels,
}: ResponsiveTableProps<T>) {
  const instanceId = useId()
  const wrapperRef = useRef<HTMLDivElement>(null)
  const loadRef = useRef<HTMLDivElement>(null)
  const [width, setWidth] = useState(1024)
  const batchSize = Math.max(1, Math.floor(growingPageSize))
  const [sourceRows, setSourceRows] = useState(rows)
  const [loaded, setLoaded] = useState(batchSize)
  if (sourceRows !== rows) {
    setSourceRows(rows)
    setLoaded(batchSize)
  }
  const visible = rows.slice(0, loaded)
  const eligibleColumns = columns.filter(
    (column) => width >= (column.minWidth ?? 0)
  )
  const mainColumns = eligibleColumns.length
    ? eligibleColumns
    : columns.slice(0, 1)
  const popinColumns = columns.filter((column) => !mainColumns.includes(column))
  const selectable = onSelectionChange != null
  const navigable = onRowNavigate != null
  const rowIds = rows.map(getRowId)
  const allSelected =
    rows.length > 0 && rowIds.every((id) => selectedIds.includes(id))
  const someSelected = rowIds.some((id) => selectedIds.includes(id))
  const selectAll = () => {
    onSelectionChange?.(
      allSelected
        ? selectedIds.filter((id) => !rowIds.includes(id))
        : [...new Set([...selectedIds, ...rowIds])]
    )
  }
  const navigation = useResponsiveTableNavigation({
    firstRow: visible[0] && getRowId(visible[0]),
    rowIds: visible.map(getRowId),
    columnIds: mainColumns.map((column) => column.id),
    open: onRowNavigate,
    selectAll,
    pageSize: batchSize,
  })

  useEffect(() => {
    const wrapper = wrapperRef.current
    if (!wrapper) return
    const measure = () => {
      if (!wrapper.closest("[hidden]")) setWidth(wrapper.clientWidth)
    }
    const observer = new ResizeObserver(measure)
    observer.observe(wrapper)
    measure()
    return () => observer.disconnect()
  }, [])
  useEffect(() => {
    const target = loadRef.current,
      wrapper = wrapperRef.current
    if (!target || !wrapper || loaded >= rows.length) return
    const root = findPageScrollContainer(wrapper, scrollContainerRef)
    const observer = new IntersectionObserver(
      (entries) => {
        if (
          entries.some((entry) => entry.isIntersecting) &&
          !wrapper.closest("[hidden]")
        ) {
          setLoaded((current) => Math.min(current + batchSize, rows.length))
        }
      },
      { root, rootMargin: "0px 0px 100px 0px" }
    )
    observer.observe(target)
    return () => observer.disconnect()
  }, [loaded, rows.length, batchSize, scrollContainerRef])

  const counts = {
    total: rows.length,
    loaded: visible.length,
    selected: rowIds.filter((id) => selectedIds.includes(id)).length,
  }
  const cellClass = (column: ResponsiveTableColumn<T>) =>
    cn(column.align === "end" && "numeric-column", column.className)
  const columnSpan =
    mainColumns.length + (selectable ? 1 : 0) + (navigable ? 1 : 0)
  const canNavigate = (target: EventTarget) =>
    !(target as HTMLElement).closest("button,a,input,[role=checkbox]")

  return (
    <div className="responsive-table" ref={wrapperRef}>
      <span className="sr-only" role="status">
        {labels.status?.(counts) ??
          `${labels.table}：共 ${counts.total} 条，已加载 ${counts.loaded} 条，已选择 ${counts.selected} 条`}
      </span>
      <Table
        className="orders-table"
        role="grid"
        aria-label={labels.table}
        aria-rowcount={rows.length + 1}
        aria-multiselectable={selectable || undefined}
        onFocusCapture={navigation.onFocusCapture}
        onBlurCapture={navigation.onBlurCapture}
        onKeyDown={navigation.onKeyDown}
      >
        <TableHeader>
          <TableRow
            data-grid-row="header"
            data-grid-key="header:row"
            tabIndex={navigation.tabIndex("header:row")}
            aria-label={labels.columnHeaders ?? "列标题"}
          >
            {selectable && (
              <TableHead
                className="checkbox-column"
                data-grid-cell="selection"
                data-grid-key="header:selection"
                tabIndex={navigation.tabIndex("header:selection")}
              >
                <Checkbox
                  aria-label={labels.selectAll ?? "选择全部行"}
                  tabIndex={navigation.contentTabIndex}
                  checked={allSelected}
                  indeterminate={!allSelected && someSelected}
                  onCheckedChange={selectAll}
                />
              </TableHead>
            )}
            {mainColumns.map((column) => (
              <TableHead
                key={column.id}
                data-grid-cell={column.id}
                data-grid-key={`header:${column.id}`}
                tabIndex={navigation.tabIndex(`header:${column.id}`)}
                className={cellClass(column)}
                aria-sort={
                  sort?.key === column.id
                    ? sort.direction === "asc"
                      ? "ascending"
                      : "descending"
                    : undefined
                }
              >
                <span className="column-label">
                  {column.label}
                  {sort?.key === column.id && (
                    <SapIcon
                      name={
                        sort.direction === "asc"
                          ? "slim-arrow-up"
                          : "slim-arrow-down"
                      }
                    />
                  )}
                </span>
              </TableHead>
            ))}
            {navigable && (
              <TableHead
                className="navigation-column"
                data-grid-cell="navigation"
                data-grid-key="header:navigation"
                tabIndex={navigation.tabIndex("header:navigation")}
              >
                <span className="sr-only">
                  {labels.navigation ?? "查看详情"}
                </span>
              </TableHead>
            )}
          </TableRow>
        </TableHeader>
        <TableBody>
          {visible.map((row, index) => {
            const id = getRowId(row),
              selected = selectedIds.includes(id)
            const popinId = `${instanceId}-popin-${id}`
            return (
              <Fragment key={id}>
                <TableRow
                  className={cn(
                    "order-row",
                    popinColumns.length > 0 && "has-popin"
                  )}
                  data-navigable={navigable}
                  data-grid-row={id}
                  data-grid-key={`${id}:row`}
                  data-state={selected ? "selected" : undefined}
                  tabIndex={navigation.tabIndex(`${id}:row`)}
                  aria-selected={selectable ? selected : undefined}
                  aria-rowindex={index + 2}
                  aria-label={getRowLabel?.(row) ?? id}
                  aria-describedby={popinColumns.length ? popinId : undefined}
                  onClick={(event) => {
                    if (canNavigate(event.target)) onRowNavigate?.(id)
                  }}
                >
                  {selectable && (
                    <TableCell
                      className="checkbox-column"
                      role="gridcell"
                      data-grid-cell="selection"
                      data-grid-key={`${id}:selection`}
                      tabIndex={navigation.tabIndex(`${id}:selection`)}
                      rowSpan={popinColumns.length ? 2 : 1}
                    >
                      <Checkbox
                        aria-label={labels.selectRow?.(row) ?? `选择 ${id}`}
                        tabIndex={navigation.contentTabIndex}
                        checked={selected}
                        onCheckedChange={(checked) =>
                          onSelectionChange(
                            checked
                              ? [...new Set([...selectedIds, id])]
                              : selectedIds.filter(
                                  (selectedId) => selectedId !== id
                                )
                          )
                        }
                      />
                    </TableCell>
                  )}
                  {mainColumns.map((column) => (
                    <TableCell
                      key={column.id}
                      role="gridcell"
                      data-grid-cell={column.id}
                      data-grid-key={`${id}:${column.id}`}
                      tabIndex={navigation.tabIndex(`${id}:${column.id}`)}
                      className={cellClass(column)}
                    >
                      {column.render(row)}
                    </TableCell>
                  ))}
                  {navigable && (
                    <TableCell
                      className="navigation-column"
                      role="gridcell"
                      data-grid-cell="navigation"
                      data-grid-key={`${id}:navigation`}
                      tabIndex={navigation.tabIndex(`${id}:navigation`)}
                      rowSpan={popinColumns.length ? 2 : 1}
                    >
                      <Button
                        variant="ghost"
                        size="icon-xs"
                        aria-label={labels.navigateRow?.(row) ?? `查看 ${id}`}
                        tabIndex={navigation.contentTabIndex}
                        title={labels.navigation ?? "查看详情"}
                        onClick={() => onRowNavigate(id)}
                      >
                        <SapIcon name="navigation-right-arrow" />
                      </Button>
                    </TableCell>
                  )}
                </TableRow>
                {popinColumns.length > 0 && (
                  <TableRow
                    className="popin-row"
                    id={popinId}
                    data-state={selected ? "selected" : undefined}
                    aria-hidden="true"
                    onClick={(event) => {
                      if (canNavigate(event.target)) onRowNavigate?.(id)
                    }}
                  >
                    <TableCell colSpan={mainColumns.length}>
                      <dl className="popin-fields">
                        {popinColumns.map((column) => (
                          <div key={column.id}>
                            <dt>{column.label}</dt>
                            <dd>{column.render(row)}</dd>
                          </div>
                        ))}
                      </dl>
                    </TableCell>
                  </TableRow>
                )}
              </Fragment>
            )
          })}
          {rows.length === 0 && (
            <TableRow>
              <TableCell colSpan={columnSpan} className="table-no-data">
                {labels.noData ?? "未找到数据。请调整筛选条件。"}
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      {loaded < rows.length && (
        <div ref={loadRef} className="load-sentinel" aria-hidden="true" />
      )}
    </div>
  )
}

import { useRef, useState, type KeyboardEvent, type FocusEvent } from "react"

// Read-only sap.m.Table navigation, based on the 1.151.0 ListBase/Table
// behavior captured in references/table-keyboard. This does not implement Edit mode.
export function useResponsiveTableNavigation({
  firstRow,
  rowIds,
  columnIds,
  open,
  selectAll,
  pageSize = 20,
}: {
  firstRow?: string
  rowIds: string[]
  columnIds: string[]
  open?: (id: string) => void
  selectAll: () => void
  pageSize?: number
}) {
  const [active, setActive] = useState<string>()
  const [contentMode, setContentMode] = useState(false)
  const previousControl = useRef(new Map<string, HTMLElement>())
  const delimiter = active?.lastIndexOf(":") ?? -1
  const activeRow = delimiter >= 0 ? active?.slice(0, delimiter) : undefined
  const existingRow = activeRow === "header" || rowIds.includes(activeRow ?? "")
  const activeColumn = delimiter >= 0 ? active?.slice(delimiter + 1) : undefined
  const existingColumn = [
    "row",
    "selection",
    "navigation",
    ...columnIds,
  ].includes(activeColumn ?? "")
  const current = existingRow
    ? existingColumn
      ? active
      : `${activeRow}:row`
    : `${firstRow ?? "header"}:row`

  function onFocusCapture(event: FocusEvent<HTMLTableElement>) {
    const target = event.target as HTMLElement
    if (target.hasAttribute("data-grid-key")) {
      setActive(target.dataset.gridKey)
      setContentMode(false)
    } else {
      const row = target.closest<HTMLElement>("[data-grid-row]")
      if (row) {
        setActive(`${row.dataset.gridRow}:row`)
        previousControl.current.set(row.dataset.gridRow!, target)
        setContentMode(true)
      }
    }
  }

  function onKeyDown(event: KeyboardEvent<HTMLTableElement>) {
    const target = event.target as HTMLElement
    const row = target.closest<HTMLElement>("[data-grid-row]")
    if (!row) return
    const isNode = target.hasAttribute("data-grid-key")
    const cell = target.closest<HTMLElement>("[data-grid-cell]")
    const controls = (node: HTMLElement) =>
      Array.from(
        node.querySelectorAll<HTMLElement>(
          'button:not([disabled]),a[href],input:not([disabled]):not([aria-hidden="true"]),[role="checkbox"]:not([aria-disabled="true"])'
        )
      )
    const focus = (node?: HTMLElement | null) => {
      if (node) {
        event.preventDefault()
        node.focus()
      }
    }
    if (!isNode) {
      if (event.key === "F2") focus(cell ?? row)
      if (event.key === "F7") focus(row)
      return
    }
    if (
      (event.ctrlKey || event.metaKey) &&
      event.key.toLowerCase() === "a" &&
      !cell
    ) {
      event.preventDefault()
      if (!event.shiftKey) selectAll()
      return
    }
    if (
      cell &&
      ["selection", "navigation"].includes(cell.dataset.gridCell ?? "") &&
      (event.key === "Enter" || event.key === " ")
    ) {
      event.preventDefault()
      controls(cell)[0]?.click()
      return
    }
    if (
      event.key === "F2" ||
      event.key === "F7" ||
      (cell && event.key === "Enter")
    ) {
      event.preventDefault()
      if (event.shiftKey) return
      const remembered =
        event.key === "F7" && !cell
          ? previousControl.current.get(row.dataset.gridRow!)
          : undefined
      focus(remembered?.isConnected ? remembered : controls(cell ?? row)[0])
      return
    }
    if (event.key === " " || event.key === "Enter") {
      event.preventDefault()
      if (!cell && event.key === "Enter" && row.dataset.gridRow !== "header")
        open?.(row.dataset.gridRow!)
      else if (!cell || cell.dataset.gridCell === "selection")
        controls(cell ?? row)[0]?.click()
      return
    }
    const rows = Array.from(
      event.currentTarget.querySelectorAll<HTMLElement>("[data-grid-row]")
    )
    const rowIndex = rows.indexOf(row)
    const cells = Array.from(
      row.querySelectorAll<HTMLElement>(":scope > [data-grid-cell]")
    )
    const cellIndex = cell ? cells.indexOf(cell) : -1
    if (
      (event.altKey || event.metaKey || event.ctrlKey) &&
      [
        "ArrowLeft",
        "ArrowRight",
        "ArrowUp",
        "ArrowDown",
        "PageUp",
        "PageDown",
      ].includes(event.key)
    )
      return
    if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
      const delta = event.key === "ArrowRight" ? 1 : -1
      focus(
        cellIndex + delta < 0
          ? row
          : cells[Math.min(cells.length - 1, cellIndex + delta)]
      )
    } else if (
      ["ArrowUp", "ArrowDown", "PageUp", "PageDown"].includes(event.key)
    ) {
      const delta =
        event.key === "ArrowUp"
          ? -1
          : event.key === "ArrowDown"
            ? 1
            : event.key === "PageUp"
              ? -pageSize
              : pageSize
      const destination =
        rows[Math.max(0, Math.min(rows.length - 1, rowIndex + delta))]
      focus(
        cell
          ? destination?.querySelectorAll<HTMLElement>(
              ":scope > [data-grid-cell]"
            )[cellIndex]
          : destination
      )
    } else if (event.key === "Home" || event.key === "End") {
      if (cell && !event.ctrlKey && !event.metaKey)
        focus(event.key === "Home" ? cells[0] : cells.at(-1))
      else {
        const destination = event.key === "Home" ? rows[0] : rows.at(-1)
        focus(
          cell
            ? destination?.querySelectorAll<HTMLElement>(
                ":scope > [data-grid-cell]"
              )[cellIndex]
            : destination
        )
      }
    }
  }

  return {
    onKeyDown,
    onFocusCapture,
    onBlurCapture: (event: FocusEvent<HTMLTableElement>) => {
      if (!event.currentTarget.contains(event.relatedTarget as Node | null))
        setContentMode(false)
    },
    tabIndex: (key: string) => (current === key ? 0 : -1),
    contentTabIndex: contentMode ? 0 : -1,
  }
}
